// ── BIG BUTTON FACTORY ────────────────────────────────────────
function Btn(props) {
  var bg = props.bg || pine, fg = props.fg || sand;
  var [pressed, setPressed] = useState(false);
  return (
    <button
      onClick={props.onClick}
      disabled={props.disabled}
      onMouseDown={function(){setPressed(true);}}
      onMouseUp={function(){setPressed(false);}}
      onTouchStart={function(){setPressed(true);}}
      onTouchEnd={function(){setPressed(false);}}
      style={{
        display:"flex", alignItems:"center", justifyContent:"center", gap:10,
        width: props.full ? "100%" : "auto",
        minHeight:64, padding:"0 28px",
        background: pressed ? darken(bg) : bg,
        color: fg, border:"none", borderRadius:14,
        fontSize:(props.small ? BASE-4 : BASE)+"px",
        fontWeight:700, fontFamily:FONT,
        cursor: props.disabled ? "not-allowed" : "pointer",
        opacity: props.disabled ? 0.55 : 1,
        boxShadow: pressed ? "none" : "0 4px 12px rgba(0,0,0,0.18)",
        transform: pressed ? "scale(0.97)" : "scale(1)",
        transition:"all 0.1s", marginBottom: props.mb || 0,
        textDecoration:"none", boxSizing:"border-box"
      }}
    >
      {props.children}
    </button>
  );
}
function darken(hex) {
  var r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
  return "rgb("+(r-30)+","+(g-30)+","+(b-30)+")";
}

// ── LINK BUTTON ───────────────────────────────────────────────
function LinkBtn(props) {
  var [pressed, setPressed] = useState(false);
  var bg = props.dark ? pine : "white";
  var fg = props.dark ? sand : pine;
  return (
    <a href={props.href} target="_blank" rel="noreferrer"
      onMouseDown={function(){setPressed(true);}} onMouseUp={function(){setPressed(false);}}
      onTouchStart={function(){setPressed(true);}} onTouchEnd={function(){setPressed(false);}}
      style={{
        display:"inline-flex", alignItems:"center", gap:6,
        minHeight:52, padding:"0 18px",
        background: pressed ? darken(bg) : bg,
        border: props.dark ? "none" : "2px solid #C8A96E",
        borderRadius:12, fontSize:(BASE-4)+"px", fontWeight:700,
        color: fg, textDecoration:"none",
        boxShadow: pressed ? "none" : "0 2px 6px rgba(0,0,0,0.1)",
        transform: pressed ? "scale(0.97)" : "scale(1)",
        transition:"all 0.1s"
      }}
    >
      {props.children}
    </a>
  );
}

